#include <iostream>
#include <cmath>

using namespace std;

int gcd (int x, int y)
{
    int gcd;
    if (x > y)
        gcd = x;
    else
        gcd = y;

    while (true)
    {
        if (x%gcd == 0 && y%gcd == 0)
            break;
        gcd--;
    }
    return gcd;
}

void diff (double x, double y, double a, double b, double &num, double &den)
{
    num = x*b - y*a;
    num = fabs (num);
    den = y*b;  
}


int main()
{
    double x,y,n,a,b;
    double min;
    int mina, minb;
    min = 1000000;

    cin>>x>>y>>n;

    if (n > y){
        int gc = gcd (x, y);
        if (gc != 1){       
            x = x/gc;
            y = y/gc;
        }
        cout<<x<<"/"<<y<<endl;
        return 0;
    }

    for (b = n; b >= 1; b--)
    {
        a = (x*b)/y;
        if (floor(a) == a){
            mina = a;
            minb = b;
            break;
        }
        else{
            double temp, tempa, tempb;
            diff(x,y,floor(a),b,tempa,tempb);
            temp = tempa/tempb;

            if(temp < min){
                mina = floor(a);
                minb = b;
                min = temp;
            }
            else if (temp == min){
                if(floor(a) < mina){
                    mina = floor(a);
                    minb = b;                   
                }
            }

            diff(x,y,ceil(a),b,tempa,tempb);        
            temp = tempa/tempb;

            if(temp < min){
                mina = ceil(a);
                minb = b;
                min = temp;
            }
            else if (temp == min){
                if(ceil(a) < mina){
                    mina = ceil(a);
                    minb = b;                   
                }
            }
        }
    }

    int gc = gcd (mina, minb);
    if (gc != 1){       
        mina = mina/gc;
        minb = minb/gc;
    }

    cout<<mina<<"/"<<minb<<endl;

    return 0;
}
